import{_ as i,o as t,c as l,aw as r}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Типизация","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js/typing/typing.md","filePath":"wiki/dev-commit/js/js/typing/typing.md"}'),e={name:"wiki/dev-commit/js/js/typing/typing.md"};function o(n,a,s,c,h,d){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="типизация" tabindex="-1">Типизация <a class="header-anchor" href="#типизация" aria-label="Permalink to &quot;Типизация&quot;">​</a></h1><h3 id="языки-программирования" tabindex="-1">Языки программирования: <a class="header-anchor" href="#языки-программирования" aria-label="Permalink to &quot;Языки программирования:&quot;">​</a></h3><ul><li>I. Типизированные</li><li>II. Нетипизированные (бестиповые) [Ассемблер, Forth и Brainfuck]</li></ul><h3 id="виды-типизации" tabindex="-1">Виды типизации <a class="header-anchor" href="#виды-типизации" aria-label="Permalink to &quot;Виды типизации&quot;">​</a></h3><ul><li><strong>Статическая типизация</strong> - тип задается при определении переменной, нельзя положить переменную другого типа. Конечные типы переменных и функций устанавливаются на этапе компиляции (компилятор точно знает, какой тип где находится) [C, Java, C#]</li><li><strong>Динамическая типизация</strong> - тип не задается. Все типы выясняются уже во время выполнения программы. Возможна запись в переменную значения другого типа [Python, JavaScript, Ruby]</li><li><strong>Сильная типизация (строгая)</strong> - язык не позволяет смешивать в выражениях различные типы и не выполняет автоматические неявные преобразования, например нельзя вычесть из строки множество [Java, Python, Haskell, Lisp]</li><li><strong>Слабая типизация (нестрогая)</strong> - неявное приведение типов. Н-р: операции сложения с разными типами данных. Автоматически выполняется множество неявных преобразований, даже если может произойти потеря точности или преобразование неоднозначно [C, JavaScript, Visual Basic, PHP]</li><li><strong>Явная типизация</strong> - тип новых переменных / функций / их аргументов нужно задавать явно [C++, D, C#]</li><li><strong>Неявная типизация</strong> - перекладывают эту задачу на компилятор / интерпретатор [PHP, Lua, JavaScript]</li></ul><h3 id="примеры-типизации" tabindex="-1">Примеры типизации <a class="header-anchor" href="#примеры-типизации" aria-label="Permalink to &quot;Примеры типизации&quot;">​</a></h3><ol><li>Статическая [C, Java,C#]</li><li>Динамическая [JavaScript, PHP, Python, Ruby]</li><li>Строгая (сильная) [Java, Python, Haskell, Lisp]</li><li>Нестрогая (слабая) [PHP, JavaScript, Visual Basic]</li><li>Явная [C++, D, C#]</li><li>Неявная [JavaScript, PHP, Lua]</li></ol>',7)])])}const P=i(e,[["render",o]]);export{u as __pageData,P as default};
